export function DesignPrimitive({
  primitive = "{{primitive}}",
  size = {{size}},
  accent = "{{accent}}",
  showComposedInto = {{showComposedInto}},
}) {
  const composed = {
    box: "Box \u2192 composes into Card, Panel, Avatar frame",
    text: "Text \u2192 composes into Label, Heading, Caption",
    icon: "Icon \u2192 composes into Button icon, Status dot",
  }[primitive];
  const shape = primitive === "text"
    ? <div style={{ fontSize: size, color: accent, fontWeight: 700, margin: "0 auto 14px" }}>Aa</div>
    : <div style={{ width: size, height: size, background: accent, margin: "0 auto 14px", borderRadius: primitive === "icon" ? "50%" : 10 }} />;
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 20, borderRadius: 12, width: 260, boxSizing: "border-box", textAlign: "center" }}>
      {shape}
      {showComposedInto && <p style={{ margin: 0, fontSize: 12, color: "#24143099" }}>{composed}</p>}
    </div>
  );
}
